def baserepr(n, b):
	repr = []
	for j in range(70):
		repr.append(n % b)
		n //= b
	return repr

def tweaks(a, p):
	twk = [a]
	for i in range(len(a)):
		if (a[i] == 0 or i == 0):
			continue

		cur = list(a)
		cur[i] -= 1; cur[i - 1] += p;
		twk.append(cur)

	return twk

def evals(a, x):
	ans = 0;
	xp = 1
	for coef in a:
		ans += coef * xp
		xp *= x
	return ans

