def issub(u, v):
    if u > v:
        return False
    if u == v:
        return True

    b = 1
    for i in range(v.bit_length()+1):
        if v & b < u & b:
            return False
        b <<= 1
    return True


def solve(N, A, B):
    vi = collections.defaultdict(list)
    for i, v in enumerate(A):
        vi[v].append(i)

